import { fileURLToPath } from 'node:url';
const ROOT = 'D:/2026 - Tuan/danang-vite-xe-may/';
const { launch, openApp, frames, pick } = await import('file:///' + ROOT + 'tests/lib.mjs');
const LANGS = (process.env.LANGS || 'vi,en,ko,ja,zh,th,ar,hi,ru').split(',');
const SEL = ['#btnSettings', '#btnViewsSheet', '#btnExExit', '#bkHint', '#bkStuck', '#drSoundBtn', '#bkView', '#bkSigL', '#bkSigR', '#bkHorn', '#bkReset', '#drMap', '#drSpeed'];
const CASES = [['desk', 1280, 720, false], ['port', 390, 844, true], ['land', 844, 390, true]];
const only = process.env.CASES ? process.env.CASES.split(',') : null;
const browser = await launch();
let bad = 0;
for (const [tag, W, H, mobile] of CASES) {
  if (only && !only.includes(tag)) continue;
  const { page } = await openApp(browser, 'http://localhost:5199/?explore=bike', { width: W, height: H, mobile });
  page.setDefaultTimeout(240000);
  await page.waitForFunction(() => window.__app.bike.active());
  for (const lang of LANGS) {
    await pick(page, '#langSelect', lang); await page.evaluate(() => window.__app.ui.closeSheets()); await frames(page, 2);
    const r = await page.evaluate((sels) => sels.flatMap((s) => [...document.querySelectorAll(s)].filter((el) => el.checkVisibility()).map((el) => { const b = el.getBoundingClientRect(); return { s, l: Math.round(b.left), t: Math.round(b.top), r: Math.round(b.right), b: Math.round(b.bottom) }; })), SEL);
    const hits = [];
    r.forEach((a, i) => r.forEach((c, j) => { if (j > i && Math.min(a.r, c.r) - Math.max(a.l, c.l) > 0.5 && Math.min(a.b, c.b) - Math.max(a.t, c.t) > 0.5) hits.push(a.s + '×' + c.s); }));
    const out = r.some((a) => a.l < 0 || a.t < 0 || a.r > W || a.b > H);
    if (hits.length || out) bad++;
    console.log(`${tag} ${lang}: ${hits.length || out ? 'LỖI ' + hits.join(',') + (out ? ' ngoài khung' : '') : 'đạt'}`);
    console.log('  ' + r.map((a) => `${a.s.slice(1)}[${a.l},${a.t},${a.r},${a.b}]`).join(' '));
    if (lang === 'ar' || lang === 'vi') await page.screenshot({ path: ROOT + `tests/screens/bike-hud-fix-${tag}-${lang}.png` });
  }
  await page.close();
}
await browser.close();
console.log('bad=' + bad);

